    41→import javax.annotation.Nullable;
    42→import java.nio.ByteBuffer;
    43→import java.util.Objects;
    44→import java.util.Set;
    45→
    46→public class JavaScriptDimFilter extends AbstractOptimizableDimFilter implements DimFilter
    47→{
    48→  private final String dimension;
    49→  private final String function;
    50→  @Nullable
    51→  private final ExtractionFn extractionFn;
    52→  @Nullable
    53→  private final FilterTuning filterTuning;
    54→  private final JavaScriptConfig config;
    55→
    56→  /**
    57→   * The field is declared volatile in order to ensure safe publication of the object
    58→   * in {@link JavaScriptPredicateFactory(String, ExtractionFn)} without worrying about final modifiers
    59→   * on the fields of the created object
    60→   *
    61→   * @see <a href="https://github.com/apache/druid/pull/6662#discussion_r237013157">
    62→   *     https://github.com/apache/druid/pull/6662#discussion_r237013157</a>
    63→   */
    64→  @MonotonicNonNull
    65→  private volatile JavaScriptPredicateFactory predicateFactory;
    66→
    67→  @JsonCreator
    68→  public JavaScriptDimFilter(
    69→      @JsonProperty("dimension") String dimension,
    70→      @JsonProperty("function") String function,
    71→      @JsonProperty("extractionFn") @Nullable ExtractionFn extractionFn,
    72→      @JsonProperty("filterTuning") @Nullable FilterTuning filterTuning,
    73→      @JacksonInject JavaScriptConfig config
    74→  )
    75→  {
    76→    Preconditions.checkArgument(dimension != null, "dimension must not be null");
    77→    Preconditions.checkArgument(function != null, "function must not be null");
    78→    this.dimension = dimension;
    79→    this.function = function;
    80→    this.extractionFn = extractionFn;
    81→    this.filterTuning = filterTuning;
    82→    this.config = config;
    83→  }
    84→
    85→  @VisibleForTesting
    86→  public JavaScriptDimFilter(
    87→      String dimension,
    88→      String function,
    89→      @Nullable ExtractionFn extractionFn,
    90→      JavaScriptConfig config
    91→  )
    92→  {
    93→    this(dimension, function, extractionFn, null, config);
    94→  }
    95→
    96→  @JsonProperty
    97→  public String getDimension()
    98→  {
    99→    return dimension;
   100→  }
   101→
   102→  @JsonProperty
   103→  public String getFunction()
   104→  {
   105→    return function;
   106→  }
   107→
   108→  @Nullable
   109→  @JsonProperty
   110→  public ExtractionFn getExtractionFn()
   111→  {
   112→    return extractionFn;
   113→  }
   114→
   115→  @Nullable
   116→  @JsonInclude(JsonInclude.Include.NON_NULL)
   117→  @JsonProperty
   118→  public FilterTuning getFilterTuning()
   119→  {
   120→    return filterTuning;
   121→  }
   122→
   123→  @Override
   124→  public byte[] getCacheKey()
   125→  {
   126→    final byte[] dimensionBytes = StringUtils.toUtf8(dimension);
   127→    final byte[] functionBytes = StringUtils.toUtf8(function);
   128→    byte[] extractionFnBytes = extractionFn == null ? new byte[0] : extractionFn.getCacheKey();
   129→
   130→    return ByteBuffer.allocate(3 + dimensionBytes.length + functionBytes.length + extractionFnBytes.length)
   131→                     .put(DimFilterUtils.JAVASCRIPT_CACHE_ID)
   132→                     .put(dimensionBytes)
   133→                     .put(DimFilterUtils.STRING_SEPARATOR)
   134→                     .put(functionBytes)
   135→                     .put(DimFilterUtils.STRING_SEPARATOR)
   136→                     .put(extractionFnBytes)
   137→                     .array();
   138→  }
   139→
   140→  @Override
   141→  public DimFilter optimize()
   142→  {
   143→    return this;
   144→  }
   145→
   146→  @Override
   147→  public Filter toFilter()
   148→  {
   149→    JavaScriptPredicateFactory predicateFactory = getPredicateFactory();
   150→    return new JavaScriptFilter(dimension, predicateFactory, filterTuning);
   151→  }
   152→
   153→  /**
   154→   * This class can be used by multiple threads, so this function should be thread-safe to avoid extra
   155→   * script compilation.
   156→   */
   157→  @EnsuresNonNull("predicateFactory")
   158→  private JavaScriptPredicateFactory getPredicateFactory()
   159→  {
   160→    // JavaScript configuration should be checked when it's actually used because someone might still want Druid
   161→    // nodes to be able to deserialize JavaScript-based objects even though JavaScript is disabled.
   162→    Preconditions.checkState(config.isEnabled(), "JavaScript is disabled");
   163→
   164→    JavaScriptPredicateFactory syncedFnPredicateFactory = predicateFactory;
   165→    if (syncedFnPredicateFactory == null) {
   166→      synchronized (config) {
   167→        syncedFnPredicateFactory = predicateFactory;
   168→        if (syncedFnPredicateFactory == null) {
   169→          syncedFnPredicateFactory = new JavaScriptPredicateFactory(function, extractionFn);
   170→          predicateFactory = syncedFnPredicateFactory;
   171→        }
   172→      }
   173→    }
   174→    return syncedFnPredicateFactory;
   175→  }
   176→
   177→  @Override
   178→  public RangeSet<String> getDimensionRangeSet(String dimension)
   179→  {
   180→    return null;
   181→  }
   182→
   183→  @Override
   184→  public Set<String> getRequiredColumns()
   185→  {
   186→    return ImmutableSet.of(dimension);
   187→  }
   188→
   189→  @Override
   190→  public boolean equals(Object o)
   191→  {
   192→    if (this == o) {
   193→      return true;
   194→    }
   195→    if (o == null || getClass() != o.getClass()) {
   196→      return false;
   197→    }
   198→    JavaScriptDimFilter that = (JavaScriptDimFilter) o;
   199→    return dimension.equals(that.dimension) &&
   200→           function.equals(that.function) &&
   201→           Objects.equals(extractionFn, that.extractionFn) &&
   202→           Objects.equals(filterTuning, that.filterTuning);
   203→  }
   204→
   205→  @Override
   206→  public int hashCode()
   207→  {
   208→    return Objects.hash(dimension, function, extractionFn, filterTuning);
   209→  }
   210→
   211→  @Override
   212→  public String toString()
   213→  {
   214→    return "JavaScriptDimFilter{" +
   215→           "dimension='" + dimension + '\'' +
   216→           ", function='" + function + '\'' +
   217→           ", extractionFn=" + extractionFn +
   218→           ", filterTuning=" + filterTuning +
   219→           '}';
   220→  }
   221→
   222→  public static class JavaScriptPredicateFactory implements DruidPredicateFactory
   223→  {
   224→    final ScriptableObject scope;
   225→    final Function fnApply;
   226→    final String script;
   227→    final ExtractionFn extractionFn;
   228→
   229→    public JavaScriptPredicateFactory(final String script, final ExtractionFn extractionFn)
   230→    {
   231→      Preconditions.checkNotNull(script, "script must not be null");
   232→      this.script = script;
   233→      this.extractionFn = extractionFn;
   234→
   235→      final Context cx = Context.enter();
